from collections import Counter, deque
def comps(g):
    H,W=len(g),len(g[0]); seen=[[False]*W for _ in range(H)]; res=[]; nb4=[(1,0),(-1,0),(0,1),(0,-1)]
    for r in range(H):
        for c in range(W):
            if not seen[r][c]:
                col=g[r][c]; q=deque([(r,c)]); seen[r][c]=True; cells=[]
                while q:
                    y,x=q.popleft(); cells.append((y,x))
                    for dy,dx in nb4:
                        ny,nx=y+dy,x+dx
                        if 0<=ny<H and 0<=nx<W and not seen[ny][nx] and g[ny][nx]==col:
                            seen[ny][nx]=True; q.append((ny,nx))
                res.append((col,cells))
    return res
