def comps(g):
    seen=[[False]*len(r) for r in g]; out=[]
    for i in range(len(g)):
        for j in range(len(g[0])):
            if not seen[i][j]:
                st=[(i,j)]; c=[]
                while st:
                    a,b=st.pop(); c.append((a,b))
                    for dx in(-1,0,1):
                        for dy in(-1,0,1):
                            x,y=a+dx,b+dy
                            if (0<=x<len(g) and 0<=y<len(g[0]) and not seen[x][y] and g[x][y]==g[a][b]):
                                seen[x][y]=True; st.append((x,y))
                out.append((g[i][j],c))
    return out
