    out=[[g[i][j] for j in range(W)] for i in range(H)]
    import heapq
    # fill: for each 8 not an anchor, nearest anchor by manhattan
    seen=set()
    for i in range(H):
        for j in range(W):
            if g[i][j]==8 and (i,j) not in seen and not any(i in tuple(a[:2]) or False for a in []):
