import numpy as np
def solve(I):
    H,W=len(I),len(I[0])
    from collections import Counter
    cnt=Counter(v for r in I for v in r)
    bg=cnt.most_common(1)[0][0]
    # find tile: largest multi-color component
    vis=set(); comps=[]
    for i in range(H):
        for j in range(W):
            if I[i][j]!=bg and (i,j) not in vis:
                st=[(i,j)]; comp=[]
                while st:
                    a,b=st.pop()
                    if (a,b) in vis: continue
                    vis.add((a,b)); comp.append((a,b))
                    for dy in(-1,0,1):
                        for dx in(-1,0,1):
                            x,y=a+dy,b+dx
                            if 0<=x<H and 0<=y<W and I[x][y]!=bg and (x,y) not in vis:
                                st.append((x,y))
                comps.append(comp)
    comps.sort(key=len, reverse=True)
    tilec=comps[0]
    rs=[a for a,b in tilec]; cs=[b for a,b in tilec]
    r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
    T=np.array([[I[r][c] for c in range(c0,c1+1)] for r in range(r0,r1+1)])
    th,tw=T.shape
    off_r=off_c=None
    O=[row[:] for row in I]
    for i in range(H):
        for j in range(W):
            if I[i][j]!=bg and (i,j) in tilec: continue
            vals=[v for row in O[max(0,i-th+1):i+1] for v in row[max(0,j-tw+1):j+1]]
            # try all offsets where marker would be a particular tile cell
            for dr in range(th):
                for dc in range(tw):
                    if T[dr][dc]==I[i][j] or True:
                        tl=(i-dr, j-dc)
                        if 0<=tl[0]<=H-th and 0<=tl[1]<=W-tw:
                            ok=True
                            for dy in range(th):
                                for dx in range(tw):
                                    rr,cc=tl[0]+dy,tl[1]+dx
                                    if O[rr][cc]!=T[dy][dx]: ok=False;break
                            if ok and (off_r is None or (off_r,off_c)==(dr,dc)):
                                off_r,off_c=dr,dc
                                for dy in range(th):
                                    for dx in range(tw):
                                        O[tl[0]+dy][tl[1]+dx]=T[dy][dx]
    return O
