                    for dy in(-1,0,1):
                        for dx in(-1,0,1):
                            x,y=a+dy,b+dx
                            if 0<=x<H and 0<=y<W and I[x][y]!=bg and (x,y) not in vis:
                                vis.add((x,y)); st.append((x,y))
                comps.append(comp)
